import com.wolinski.shop.money.Money;
import com.wolinski.shop.platform.ShopProblem;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/** A percentage discount, held as whole basis points (1% = 100 bp, 0.01% = 1 bp). */
final class Discount {

    private static final int BASIS_POINTS_PER_WHOLE = 10_000;
    private static final Pattern PERCENT = Pattern.compile("(\\d{1,3})(?:\\.(\\d{1,2}))?");

    private final long basisPoints;

    private Discount(long basisPoints) {
        this.basisPoints = basisPoints;
    }

    /** Parses admin-form text such as "12.5" or "0.25". Anything else is rejected. */
    static Discount parsePercent(String text) {
        if (null == text) {
            throw new ShopProblem("INVALID_PERCENT", "Discount percent is missing");
        }
        Matcher m = PERCENT.matcher(text.trim());
        if (false == m.matches()) {
            throw new ShopProblem("INVALID_PERCENT", "Discount percent is not a number: " + text);
        }
        long whole = Long.parseLong(m.group(1));
        String fraction = m.group(2);
        long hundredths = null == fraction ? 0 : Long.parseLong(fraction.length() == 1 ? fraction + "0" : fraction);
        long basisPoints = whole * 100 + hundredths;
        if (basisPoints > BASIS_POINTS_PER_WHOLE) {
            throw new ShopProblem("PERCENT_OUT_OF_RANGE", "Discount percent must be between 0 and 100: " + text);
        }
        return new Discount(basisPoints);
    }

    /** The discount amount for a total, rounded half up to a whole minor unit. */
    Money of(Money total) {
        long numerator = Math.multiplyExact(total.minorUnits(), basisPoints);
        long amount = Math.floorDiv(numerator + BASIS_POINTS_PER_WHOLE / 2, BASIS_POINTS_PER_WHOLE);
        return new Money(amount, total.currency());
    }
}
}

